import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        String s = sc.next();
        String t = sc.next();
        sc.close();

        if (t.charAt(0) == t.charAt(1)) {
            int count = 0;
            for (char c : s.toCharArray()) {
                if (c == t.charAt(0)) count++;
            }
            int x = Math.min(count + k, n);
            System.out.println((long) x * (x - 1) / 2);
            return;
        }

        // f[i][j][cnt0] : i chars processed, j changes used, cnt0 count of t[0]
        // Dimensions: (n+1) x (k+1) x (n+1)
        int[][][] f = new int[n + 1][k + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int c = 0; c <= n; c++) {
                    f[i][j][c] = -100000; // -1e5
                }
            }
        }
        f[0][0][0] = 0;

        for (int i = 0; i <= n; i++) { // For(0, n, i)
            for (int j = 0; j <= k; j++) { // For(0, k, j)
                for (int cnt0 = 0; cnt0 <= i; cnt0++) { // For(0, i, cnt0)
                    if (f[i][j][cnt0] < 0) continue;

                    boolean e0 = (i < n && s.charAt(i) == t.charAt(0));
                    boolean e1 = (i < n && s.charAt(i) == t.charAt(1));

                    if (i < n) {
                        // Keep current char
                        int nc0 = cnt0 + (e0 ? 1 : 0);
                        int val = f[i][j][cnt0] + (e1 ? cnt0 : 0);
                        if (val > f[i + 1][j][nc0]) {
                            f[i + 1][j][nc0] = val;
                        }

                        // Change to t[0]
                        if (j < k) {
                            if (f[i][j][cnt0] > f[i + 1][j + 1][cnt0 + 1]) {
                                f[i + 1][j + 1][cnt0 + 1] = f[i][j][cnt0];
                            }
                        }

                        // Change to t[1]
                        if (j < k) {
                            // JS: f[i + 1][j + 1][cnt0] = Math.max(f[i + 1][j][cnt0], f[i][j][cnt0] + cnt0);
                            int val1 = f[i][j][cnt0] + cnt0;
                            int val2 = f[i + 1][j][cnt0]; // Note: uses same i+1, j state
                            int maxVal = Math.max(val1, val2);
                            if (maxVal > f[i + 1][j + 1][cnt0]) {
                                f[i + 1][j + 1][cnt0] = maxVal;
                            }
                        }
                    }
                }
            }
        }

        int ans = 0;
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= n; j++) {
                if (f[n][i][j] > ans) {
                    ans = f[n][i][j];
                }
            }
        }
        System.out.println(ans);
    }
}

